"use client";
import React from "react";
import ScrollStack, { ScrollStackItem } from "@/components/ScrollStack";

const Features = () => {
  return (
    <section className="h-[300vh] bg-amber-200 relative">
      <ScrollStack className="px-6 py-20">
        <ScrollStackItem>
          <h2>Card 1</h2>
          <p>This is the first card in the stack</p>
        </ScrollStackItem>
        <ScrollStackItem>
          <h2>Card 2</h2>
          <p>This is the second card in the stack</p>
        </ScrollStackItem>
        <ScrollStackItem>
          <h2>Card 3</h2>
          <p>This is the third card in the stack</p>
        </ScrollStackItem>
      </ScrollStack>
    </section>
  );
};

export default Features;
